// =============================================
// RENDERING  (CSP-safe: no inline onclick)
// =============================================
let activeFilter='all';
let currentCalc=null;

// Flat lookup map: scoreName -> {score, color}
const SCORE_MAP = {};
DIVISIONS.forEach(div => div.scores.forEach(s => {
  SCORE_MAP[s.name] = { score: s, color: div.color };
}));

function buildCard(score, divColor) {
  const hasCalc = !!CALCS[score.name];
  // Use data-score-name instead of onclick
  return `<div class="card${hasCalc?' has-calc':''}"
    data-score-name="${score.name}"
    style="cursor:pointer"
  ><div style="position:absolute;left:0;top:0;bottom:0;width:3px;background:${divColor};border-radius:8px 0 0 8px"></div>
    <div class="cn">${score.name}</div>
    <div class="cf">${score.full}</div>
    <div class="cu">${score.use}</div>
    <div class="tags">${score.tags.map(t=>`<span class="tag tag-${t}">${t}</span>`).join('')}</div>
    <div class="ref">📄 ${score.ref}</div>
  </div>`;
}

function renderAll(filter='',tagFilter='all') {
  const main=document.getElementById('main');
  let html='';let total=0;let vis=0;
  DIVISIONS.forEach(div=>{
    const f=filter.toLowerCase();
    const filtered=div.scores.filter(s=>{
      const m=!filter||(s.name.toLowerCase().includes(f)||s.full.toLowerCase().includes(f)||s.use.toLowerCase().includes(f));
      const t=tagFilter==='all'||s.tags.includes(tagFilter);
      return m&&t;
    });
    total+=div.scores.length;
    if(!filtered.length) return;
    vis+=filtered.length;
    html+=`<div class="section">
      <div class="sec-hdr">
        <div class="sdot" style="background:${div.color};box-shadow:0 0 8px ${div.color}60"></div>
        <span class="stitle">${div.name}</span>
        <span class="scnt">${filtered.length}</span>
      </div>
      <div class="grid">${filtered.map(s=>buildCard(s,div.color)).join('')}</div>
    </div>`;
  });
  main.querySelectorAll('.section').forEach(s=>s.remove());
  main.insertAdjacentHTML('afterbegin',html);
  document.getElementById('tScores').textContent=total;
  document.getElementById('tCalc').textContent=Object.keys(CALCS).length;
  document.getElementById('tDiv').textContent=DIVISIONS.length;
  document.getElementById('tShow').textContent=vis;
  document.getElementById('nores').style.display=vis===0?'block':'none';
}

// ── CARD CLICK via event delegation ─────────────────
document.getElementById('main').addEventListener('click', function(e) {
  var card = e.target.closest('[data-score-name]');
  if (!card) return;
  var name = card.getAttribute('data-score-name');
  if (!name || !SCORE_MAP[name]) return;
  var entry = SCORE_MAP[name];
  openModal(entry.score.name, entry.score.full, entry.score.ref, entry.color);
});

function openModal(name, full, ref, color) {
  document.getElementById('m-badge').textContent=name;
  document.getElementById('m-title').textContent=name;
  document.getElementById('m-sub').textContent=full;
  document.getElementById('m-ref').textContent='📄 '+ref;
  document.getElementById('m-badge').style.color=color;
  const body=document.getElementById('m-body');
  if(CALCS[name]) {
    currentCalc={name,ref,full,color};
    body.innerHTML=buildCalcForm(name, color);
  } else if(REFS[name]) {
    currentCalc=null;
    body.innerHTML=buildRefPanel(name, color);
  } else {
    currentCalc=null;
    var entry=SCORE_MAP[name];
    body.innerHTML='<div class="ref-panel"><h4>Panduan Klinis</h4>'
      +(entry?'<div style="font-size:12px;color:var(--dim);line-height:1.7">'+entry.score.use+'</div>':'')
      +'<div style="margin-top:12px;font-size:11px;color:var(--mut);font-style:italic">Kalkulator interaktif sedang dalam pengembangan.</div></div>';
  }
  document.getElementById('overlay').classList.add('open');
  document.getElementById('modal').classList.add('open');
}

function buildCalcForm(name, color) {
  var c=CALCS[name];
  if(name==='NIHSS') return buildNihssForm(c, color);
  var html='';
  if(c.formula) html+='<div class="formula-box"><strong>Formula:</strong> '+c.formula+'</div>';
  if(c.image) html+='<div style="margin:8px 0 14px;text-align:center"><img src="'+c.image+'" alt="'+name+'" style="max-width:100%;border-radius:8px;border:1px solid rgba(255,255,255,.08);display:block;margin:0 auto">'+(c.imageCaption?'<div style="font-size:11px;color:var(--mut);margin-top:6px;font-style:italic;line-height:1.5">'+c.imageCaption+'</div>':'')+'</div>';
  if(c.customIntro) html+=c.customIntro;
  html+='<div id="calc-fields">';
  var fieldById={};c.fields.forEach(function(f){fieldById[f.id]=f;});
  function chipHTML(f){
    return '<div class="aspect-chip" data-toggle-id="'+f.id+'" title="'+f.label.replace(/"/g,'&quot;')+'">'
      +'<input type="hidden" id="f_'+f.id+'" value="0">'
      +(f.short||f.id)
      +(f.tip?'<span class="ac-tip">'+f.tip+'</span>':'')
      +'</div>';
  }
  var toggleRendered={};
  if(c.toggleColumns){
    html+='<div class="aspect-grid">';
    c.toggleColumns.forEach(function(col){
      html+='<div class="aspect-col">';
      col.forEach(function(id){var f=fieldById[id];if(!f)return;toggleRendered[id]=1;html+=chipHTML(f);});
      html+='</div>';
    });
    html+='</div>';
  }
  var inGrid=false;
  c.fields.forEach(function(f){
    if(f.type==='toggle'){
      if(toggleRendered[f.id])return;
      if(!inGrid){html+='<div class="aspect-grid">';inGrid=true;}
      html+=chipHTML(f);
      return;
    }
    if(inGrid){html+='</div>';inGrid=false;}
    html+='<div class="fgroup"><label class="flabel">'+f.label+(f.note?'<span class="fnote">— '+f.note+'</span>':'')+'</label>';
    if(f.type==='sel'){
      html+='<select class="fi" id="f_'+f.id+'">'+f.opts.map(function(o){return '<option value="'+o.v+'">'+o.l+'</option>';}).join('')+'</select>';
    } else if(f.type==='num'){
      html+='<input class="fi" type="number" id="f_'+f.id+'" min="'+(f.min||0)+'" max="'+(f.max||999)+'" placeholder="'+(f.placeholder||'')+'">';
    }
    html+='</div>';
  });
  if(inGrid)html+='</div>';
  html+='</div>';
  // data-action instead of onclick
  html+='<button class="calc-btn" data-action="calculate" data-name="'+name+'">⚡ Hitung Score</button>';
  html+='<div class="result-box" id="result-box"></div>';
  return html;
}

function buildNihssForm(c, color) {
  function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
  var html='';
  if(c.formula) html+='<div class="formula-box"><strong>Formula:</strong> '+esc(c.formula)+'</div>';
  html+='<div class="nihss-score-box">'
     +    '<div class="nihss-score-left">'
     +      '<div class="nihss-score-cap">Skor</div>'
     +      '<div class="nihss-score-num" id="nihss-score-num">0</div>'
     +      '<div class="nihss-score-max">/ 42</div>'
     +    '</div>'
     +    '<div class="nihss-score-right">'
     +      '<div class="nihss-grade-pill" id="nihss-grade-pill">Tidak Ada Gejala / Minor</div>'
     +      '<div class="nihss-range" id="nihss-range">0 – 4 poin</div>'
     +      '<div class="nihss-progress"><div class="nihss-progress-bar" id="nihss-progress-bar"></div></div>'
     +    '</div>'
     +  '</div>';
  html+='<div id="calc-fields">';
  c.fields.forEach(function(f){
    var m=String(f.label).match(/^(\d+[a-z]?)\.\s*(.+)$/);
    var num=m?m[1]:'';
    var title=m?m[2]:f.label;
    html+='<div class="nihss-item" data-item="'+f.id+'">'
       +    '<button type="button" class="nihss-item-head" data-action="toggle-item" data-id="'+f.id+'">'
       +      (num?'<span class="nihss-num">'+esc(num)+'</span>':'')
       +      '<span class="nihss-title">'+esc(title)+(f.note?'<span class="nihss-note">— '+esc(f.note)+'</span>':'')+'</span>'
       +      '<span class="nihss-caret">−</span>'
       +    '</button>'
       +    '<div class="nihss-item-body">'
       +      '<input type="hidden" id="f_'+f.id+'" value="0">';
    f.opts.forEach(function(o,i){
      var lbl=String(o.l);
      var om=lbl.match(/^\s*\d+\s*[—\-–]\s*(.+)$/);
      var displayLbl=om?om[1]:lbl;
      html+='<div class="nihss-opt'+(o.v===0?' sel':'')+'" data-action="pick-nihss" data-fid="'+f.id+'" data-val="'+o.v+'">'
         +    '<span class="nihss-radio"></span>'
         +    '<span class="nihss-val">'+esc(String(o.v))+'</span>'
         +    '<span class="nihss-lbl">'+esc(displayLbl)+'</span>'
         + '</div>';
    });
    html+='</div></div>';
  });
  html+='</div>';
  html+='<div class="result-box" id="result-box"></div>';
  return html;
}

function nihssRecalc() {
  var c=CALCS['NIHSS'];if(!c)return;
  var vals={};
  c.fields.forEach(function(f){
    var el=document.getElementById('f_'+f.id);
    vals[f.id]=el?Number(el.value):0;
  });
  var total=c.calc(vals);
  var info=c.interp(total);
  var numEl=document.getElementById('nihss-score-num');
  var gradeEl=document.getElementById('nihss-grade-pill');
  var rangeEl=document.getElementById('nihss-range');
  var barEl=document.getElementById('nihss-progress-bar');
  if(numEl){numEl.textContent=total;numEl.style.color=info.color;}
  if(gradeEl){
    gradeEl.textContent=info.grade.toUpperCase();
    gradeEl.style.borderColor=info.color;
    gradeEl.style.color=info.color;
    gradeEl.style.background=info.color+'12';
  }
  if(rangeEl){
    var ranges={0:'0 poin',1:'1 – 4 poin',5:'5 – 15 poin',16:'16 – 20 poin',21:'21 – 42 poin'};
    var key= total===0?0 : total<=4?1 : total<=15?5 : total<=20?16 : 21;
    rangeEl.textContent=ranges[key];
  }
  if(barEl){
    barEl.style.width=Math.min(100,(total/42)*100)+'%';
    barEl.style.background=info.color;
  }
}

function buildRefPanel(name, color) {
  var r=REFS[name];
  var html='<div class="ref-panel" data-ref="'+name+'"><h4>'+(r.subtitle||'Kriteria & Interpretasi')+'</h4>';
  r.items.forEach(function(item){
    html+='<div class="grade-row"><div class="grade-num" style="color:'+color+'">'+item.label+'</div><div class="grade-desc" style="white-space:pre-wrap">'+item.val+'</div></div>';
  });
  html+='</div>';
  html+=buildCopyBtn('ref',name);
  return html;
}

function buildCopyBtn(type, id) {
  return '<button class="copy-btn" id="copy-btn-'+type+'" data-action="copy" data-type="'+type+'" data-id="'+id+'">'
    +'<svg fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"/></svg>'
    +' Copy Hasil</button>';
}

// ── MODAL BODY button delegation ─────────────────────
document.getElementById('m-body').addEventListener('click', function(e) {
  var chip = e.target.closest('.aspect-chip');
  if (chip) {
    var hit = chip.classList.toggle('hit');
    var input = chip.querySelector('input[type="hidden"]');
    if (input) input.value = hit ? '1' : '0';
    if (currentCalc) calculate(currentCalc.name, currentCalc.color, {noScroll:true});
    return;
  }
  var btn = e.target.closest('[data-action]');
  if (!btn) return;
  if (btn.dataset.action === 'calculate') {
    calculate(btn.dataset.name, currentCalc ? currentCalc.color : '#00d4ff');
  }
  if (btn.dataset.action === 'copy') {
    copyResult(btn.dataset.type, btn.dataset.id);
  }
  if (btn.dataset.action === 'pick-nihss') {
    var fid = btn.dataset.fid;
    var val = btn.dataset.val;
    var input = document.getElementById('f_'+fid);
    if (input) input.value = val;
    var item = btn.closest('.nihss-item');
    if (item) item.querySelectorAll('.nihss-opt').forEach(function(o){o.classList.remove('sel');});
    btn.classList.add('sel');
    nihssRecalc();
  }
  if (btn.dataset.action === 'toggle-item') {
    var it = btn.closest('.nihss-item');
    if (it) it.classList.toggle('collapsed');
  }
});

function calculate(name, color, opts) {
  var c=CALCS[name];
  if(!c) return;
  var vals={};var valid=true;
  c.fields.forEach(function(f){
    var el=document.getElementById('f_'+f.id);
    if(!el){valid=false;return;}
    var raw=el.value;
    if(raw===''||raw===null||raw===undefined){valid=false;return;}
    var num=parseFloat(raw);
    vals[f.id]=isNaN(num)?raw:num;
  });
  if(!valid){alert('Harap isi semua field terlebih dahulu.');return;}
  var score=c.calc(vals);
  var interp=c.interp(score, vals);
  var box=document.getElementById('result-box');
  box.className='result-box show';
  box.style.background='linear-gradient(135deg, '+interp.color+'18, '+interp.color+'08)';
  box.style.border='1px solid '+interp.color+'40';
  box.innerHTML='<div class="res-top"><div>'
    +'<div class="res-score" style="color:'+interp.color+'">'+interp.disp+'</div>'
    +'<div class="res-grade" style="color:'+interp.color+'">'+interp.icon+' '+interp.grade+'</div>'
    +'</div></div>'
    +'<div class="res-detail">'+interp.detail+'</div>'
    +buildCopyBtn('calc',name);
  window._lastResult={name:name,full:currentCalc?currentCalc.full:'',score:interp.disp,grade:interp.grade,detail:interp.detail,fields:c.fields,vals:vals,ref:currentCalc?currentCalc.ref:''};
  if(!opts||!opts.noScroll)box.scrollIntoView({behavior:'smooth',block:'nearest'});
}

function copyResult(type, name) {
  var text='';
  var btn=document.getElementById('copy-btn-'+type);
  if(type==='calc' && window._lastResult) {
    var r=window._lastResult;
    var now=new Date().toLocaleString('id-ID');
    text='=== '+r.name+' — '+(r.full||'')+' ===\n';
    text+='Tanggal: '+now+'\n\n';
    text+='📊 SKOR: '+r.score+'\n';
    text+='📋 INTERPRETASI: '+r.grade+'\n\n';
    text+='DETAIL:\n'+r.detail+'\n\nNILAI INPUT:\n';
    r.fields.forEach(function(f){
      var v=r.vals[f.id];
      var optLabel=f.opts?((f.opts.find(function(o){return parseFloat(o.v)===v;})||{}).l||v):v;
      text+='• '+f.label+': '+optLabel+'\n';
    });
    text+='\n📄 Referensi: '+(r.ref||'');
  } else if(type==='ref' && REFS[name]) {
    var r2=REFS[name];
    text='=== '+name+' — '+r2.title+' ===\n';
    r2.items.forEach(function(item){ text+='\n'+item.label+':\n'+item.val+'\n'; });
  }
  if(!text) return;
  var flashBtn=function(){
    if(!btn) return;
    btn.textContent='✓ Tersalin!';btn.classList.add('copied');
    setTimeout(function(){
      btn.innerHTML='<svg fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"/></svg> Copy Hasil';
      btn.classList.remove('copied');
    },2000);
  };
  if(navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(flashBtn).catch(function(){
      var ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';
      document.body.appendChild(ta);ta.select();try{document.execCommand('copy');}catch(e){}document.body.removeChild(ta);
      flashBtn();
    });
  } else {
    var ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';
    document.body.appendChild(ta);ta.select();try{document.execCommand('copy');}catch(e){}document.body.removeChild(ta);
    flashBtn();
  }
}

function closeModal(){
  document.getElementById('overlay').classList.remove('open');
  document.getElementById('modal').classList.remove('open');
  currentCalc=null;
}

// ── STATIC LISTENERS ──────────────────────────────────
document.getElementById('overlay').addEventListener('click', closeModal);
document.getElementById('modal-close-btn').addEventListener('click', closeModal);
document.addEventListener('keydown', function(e){ if(e.key==='Escape') closeModal(); });

document.getElementById('srch').addEventListener('input', function(e){
  clearTimeout(window._srt);
  window._srt=setTimeout(function(){ renderAll(e.target.value, activeFilter); }, 200);
});

document.querySelectorAll('.fb').forEach(function(btn){
  btn.addEventListener('click', function(){
    document.querySelectorAll('.fb').forEach(function(b){ b.classList.remove('on'); });
    btn.classList.add('on');
    activeFilter=btn.dataset.f;
    renderAll(document.getElementById('srch').value, activeFilter);
  });
});

// INIT
renderAll();

// ── AUTO-OPEN FROM URL PARAM ──────────────────────────
(function(){
  var params=new URLSearchParams(window.location.search);
  var scoreName=params.get('score');
  if(!scoreName) return;
  setTimeout(function(){
    var entry=SCORE_MAP[scoreName];
    if(!entry) return;
    document.querySelectorAll('[data-score-name]').forEach(function(card){
      if(card.getAttribute('data-score-name')===scoreName){
        card.style.transition='box-shadow 0.4s';
        card.style.boxShadow='0 0 0 2px '+entry.color+', 0 0 30px '+entry.color+'40';
        card.scrollIntoView({behavior:'smooth',block:'center'});
        setTimeout(function(){card.style.boxShadow='';},2000);
      }
    });
    openModal(entry.score.name, entry.score.full, entry.score.ref, entry.color);
    window.history.replaceState({},'',window.location.pathname);
  }, 150);
})();
